def test_core_packages_exclude_plugins_and_full_only_adds_runtime(self) -> None:
        lite = {path.relative_to(ROOT).as_posix() for path in PACKAGE_RELEASE.source_files(False)}
        full = {path.relative_to(ROOT).as_posix() for path in PACKAGE_RELEASE.source_files(True)}
        self.assertTrue(set(PACKAGE_RELEASE.CORE_REQUIRED_FILES) <= lite)
        self.assertFalse(any(path == "plugins" or path.startswith("plugins/") for path in lite | full))
        self.assertLess(lite, full)
        self.assertTrue(all(path.startswith("assets/runtime/win-x64/") for path in full - lite))

def test_mechanical_fragments_do_not_enter_fts_terms(self) -> None:
        for text, fragment in (
            ("打包不满足", "包不满"),
            ("是否会回", "否会回"),
            ("回的检索", "回的检"),
        ):
            self.assertNotIn(fragment, fts_query_terms(text))
            self.assertNotIn(fragment, search_terms(text))
            self.assertIn(text, search_terms(text))

def test_mixed_camel_identifier_order_is_fixed(self) -> None:
        self.assertEqual(
            search_terms("OrderService 服务修改"),
            ["orderservice", "服务修改", "service", "order", "务修改", "服务修", "修改", "务修", "服务"],
        )
        self.assertEqual(explicit_anchors("OrderService 服务修改"), ["orderservice"])

def git(repo: Path, *args: str) -> str:
    completed = subprocess.run(["git", "-C", str(repo), *args], text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if completed.returncode:
        raise RuntimeError(completed.stderr)
    return completed.stdout.strip()

def review_all(output: Path) -> None:
    state = json.loads((output / "state.json").read_text(encoding="utf-8"))
    for batch in state["parse_batches"]:
        if not (output / "chunks" / batch["id"] / "candidate.json").is_file():
            build_chunk(output, batch["id"], "all")
    state = json.loads((output / "state.json").read_text(encoding="utf-8"))
    for pack in state["review_packs"]:
        if pack["status"] == "passed":
            continue
        template = json.loads(Path(pack["review_template_path"]).read_text(encoding="utf-8"))
        for item in template["reviews"]:
            item["status"] = "agent-reviewed"
            item["evidence_note"] = "Agent 已重新打开固定 Git 源码范围，逐项核对名称、范围、分支和调用关系后确认说明。"
            if pack["kind"] == "appendix-review":
                item["description_zh"] = "该局部代码负责完成所属流程中的辅助步骤，并把确定结果交给主流程继续使用。"
            else:
                item["meaning_zh"] = "该代码页说明固定源码范围内的主要实现、输入条件和输出结果。"
                item["role_zh"] = "它负责组织当前代码单元的执行步骤，并与相邻函数形成可追踪的调用关系。"
                item["change_when_zh"] = "当输入约定、执行步骤、返回结果或调用关系变化时，需要修改并重新核对该代码单元。"
        path = output / "test-reviews" / f"{pack['id']}.json"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(template, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        review_pack(output, pack["id"], path)

